import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { writeFile } from "./build.utils";

const buildDir = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(buildDir, "..");
const iconSetDir = path.join(rootDir, "icon-set");

interface IconType {
  name: string;
  regex: RegExp;
  convert: (value: string) => string;
}

const cjsBanner = (setName: string): string => `/**
 * DO NOT EDIT THIS FILE. It is automatically generated
 * from its .mjs counterpart (same filename but with .mjs extension).
 * Edit that file instead (${setName}).
 */
`;

const svgIconSetBanner = (setName: string): string => `/*
 * DO NOT EDIT THIS FILE. It is automatically generated
 * from its webfont counterpart (same filename without "svg-" prefix).
 * Edit that file instead (${setName}.mjs).
 */`;

function convert(str: string): string {
  return str.replace(/(-\w)/g, (match) => match[1].toUpperCase());
}

function materialConvert(str: string, oldPrefix: string, newPrefix: string): string {
  if (oldPrefix !== "") {
    str = str.substring(oldPrefix.length);
  }

  return (newPrefix + str).replace(/(_\w)/g, (match) => match[1].toUpperCase());
}

const iconTypes: IconType[] = [
  {
    name: "material-icons-outlined",
    regex: /^o_/,
    convert: (str) => materialConvert(str, "o_", "outlined_"),
  },
  {
    name: "material-icons-round",
    regex: /^r_/,
    convert: (str) => materialConvert(str, "r_", "round_"),
  },
  {
    name: "material-icons-sharp",
    regex: /^s_/,
    convert: (str) => materialConvert(str, "s_", "sharp_"),
  },
  {
    name: "material-symbols-outlined",
    regex: /^sym_o_/,
    convert: (str) => materialConvert(str, "sym_o_", "sym_outlined_"),
  },
  {
    name: "material-symbols-rounded",
    regex: /^sym_r_/,
    convert: (str) => materialConvert(str, "sym_r_", "sym_rounded_"),
  },
  {
    name: "material-symbols-sharp",
    regex: /^sym_s_/,
    convert: (str) => materialConvert(str, "sym_s_", "sym_sharp_"),
  },
  {
    name: "mdi-v4",
    regex: /^mdi-/,
    convert,
  },
  {
    name: "mdi-v5",
    regex: /^mdi-/,
    convert,
  },
  {
    name: "mdi-v6",
    regex: /^mdi-/,
    convert,
  },
  {
    name: "ionicons-v4",
    regex: /^ion-/,
    convert,
  },
  {
    name: "fontawesome-v5",
    regex: /^fa[brs] fa-/,
    convert: (str) => convert(str.replace(" fa-", "-")),
  },
  {
    name: "fontawesome-v6",
    regex: /^fa[brs] fa-/,
    convert: (str) => convert(str.replace(" fa-", "-")),
  },
  {
    name: "eva-icons",
    regex: /^eva-/,
    convert,
  },
  {
    name: "themify",
    regex: /^ti-/,
    convert,
  },
  {
    name: "line-awesome",
    regex: /^la[brs] la-/,
    convert: (str) =>
      convert(
        (str.startsWith("las la-") === true ? str + "-solid" : str).replace(/^la[brs] la-/, "la-"),
      ),
  },
  {
    name: "bootstrap-icons",
    regex: /^bi-/,
    convert,
  },
  {
    name: "material-icons",
    regex: /./,
    convert: (str) => materialConvert(str, "", "mat_"),
  },
];

const iconNames = iconTypes.map((type) => type.name);
const splitDelimiter = "export default {";

function convertWebfont(
  name: string,
  preferredImportName: string,
): { importName: string; variableName: string } {
  const type =
    iconTypes.find((item) => item.name === preferredImportName && item.regex.test(name)) ||
    iconTypes.find((item) => item.regex.test(name)) ||
    iconTypes[0];

  return {
    importName: type.name,
    variableName: type.convert(name),
  };
}

function toImportList(): Record<string, string[]> {
  return Object.fromEntries(iconNames.map((name) => [name, []]));
}

function splitContent(str: string): { outsideOfExport: string; insideOfExport: string } {
  const content = str.split(splitDelimiter);

  return {
    outsideOfExport: content[0],
    insideOfExport: splitDelimiter + content[1],
  };
}

async function generateSvgFile(type: IconType): Promise<void> {
  const source = path.join(iconSetDir, `${type.name}.mjs`);

  if (fs.existsSync(source) === false) {
    return;
  }

  const original = fs.readFileSync(source, "utf-8");
  const { outsideOfExport, insideOfExport } = splitContent(original);
  const importList = toImportList();

  const contentString = insideOfExport
    .replace(/name: '(.+)'/, 'name: ""')
    .replace(/'(.+)'/g, (match) => {
      const { importName, variableName } = convertWebfont(
        match.substring(1, match.length - 1),
        type.name,
      );

      if (importList[importName].includes(variableName) === false) {
        importList[importName].push(variableName);
      }

      return variableName;
    })
    .replace(/name: ""/, `name: 'svg-${type.name}'`);

  const importString = Object.keys(importList)
    .filter((listName) => importList[listName].length > 0)
    .map(
      (listName) =>
        `import {\n  ${importList[listName].join(",\n  ")}\n} from '@quasar/extras/${listName}/index.mjs'`,
    )
    .join("\n\n");

  const content = [svgIconSetBanner(type.name), importString, outsideOfExport, contentString]
    .filter(Boolean)
    .join("\n\n");

  await writeFile(path.join(iconSetDir, `svg-${type.name}.mjs`), content);
}

function convertToCjs(content: string, banner = ""): string {
  return banner + content.replace(/export default\s+/, "module.exports = ");
}

async function generateCjsCounterparts(): Promise<void> {
  const files = fs
    .readdirSync(iconSetDir)
    .filter((file) => file.endsWith(".mjs"))
    .sort((a, b) => a.localeCompare(b));

  await Promise.all(
    files.map((file) => {
      const fullPath = path.join(iconSetDir, file);
      const content = fs.readFileSync(fullPath, "utf-8");
      const banner = file.includes("svg") ? "" : cjsBanner(path.basename(file));

      return writeFile(fullPath.replace(/\.mjs$/, ".js"), convertToCjs(content, banner));
    }),
  );
}

export async function buildIconSets(): Promise<void> {
  await Promise.all(iconTypes.map(generateSvgFile));
  await generateCjsCounterparts();
}

if (import.meta.url === `file://${process.argv[1]}`) {
  buildIconSets().catch((err: unknown) => {
    console.error(err);
    process.exit(1);
  });
}
